class Solution {
  public double separateSquares(int[][] squares) {
    double total = 0, lo = Double.MAX_VALUE, hi = 0;
    for (int[] s : squares) {
      total += (double) s[2] * s[2];
      lo = Math.min(lo, s[1]);
      hi = Math.max(hi, (double) s[1] + s[2]);
    }
    for (int iter = 0; iter < 100; iter++) {
      double mid = (lo + hi) / 2;
      if (areaBelow(squares, mid) * 2 >= total) hi = mid;
      else lo = mid;
    }
    return hi;
  }

  private double areaBelow(int[][] squares, double y) {
    double area = 0;
    for (int[] s : squares) {
      double height = Math.min(Math.max(y - s[1], 0), s[2]);
      area += height * s[2];
    }
    return area;
  }
}
